INPUT: partial cube pc, codes of length n
out <- empty map
for i in 0..n-1:
    W0 <- { v in pc : v[i] = 0 }
    W1 <- { v in pc : v[i] = 1 }
    if W0 nonempty and W1 nonempty:
        out[i] <- (W0, W1)     # theta-class i and its opposite semicubes
return out
